-- Paste and RUN THE ENTIRE FILE ONCE in the Production SQL Console.
-- Any failure: ROLLBACK in the same SQL session. Never run selected fragments.

BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';
LOCK TABLE public.white_label_requests IN ACCESS EXCLUSIVE MODE;
LOCK TABLE public.module_catalog IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public.entitlement_definitions IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public.asset_catalog IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public.network_catalog IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public.asset_network_catalog IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public.landing_products IN SHARE ROW EXCLUSIVE MODE;

-- Preconditions: freshness, exact-scope drift, RLS and active trigger checks.
DO $qx_global$
DECLARE captured_at timestamptz := (convert_from(decode('22323032362d31302d30375432333a33373a33362e3638303930352b30303a303022','hex'),'UTF8')::jsonb#>>'{}')::timestamptz;
BEGIN
IF captured_at < clock_timestamp()-interval '60 minutes'
 OR captured_at > clock_timestamp()+interval '1 minute' THEN RAISE EXCEPTION 'Preflight expired; refreeze after review.'; END IF;
IF EXISTS(SELECT 1 FROM pg_class WHERE oid='public.module_catalog'::regclass AND (relrowsecurity OR relforcerowsecurity))
      OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.module_catalog'::regclass AND NOT tgisinternal AND tgenabled<>'D') THEN
      RAISE EXCEPTION 'Unexpected security/trigger configuration on module_catalog; review required.'; END IF;
    IF (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY key),'[]'::jsonb) FROM (SELECT key,name,description,category,sandbox_available,definition FROM public.module_catalog WHERE key IN ('crypto_exchange','website','merchant_api','crypto_payments','crypto_card','staking','earn','dex','telegram_bot','telegram_mini_app','whatsapp_bot','ios_app','android_app','crypto_engine','rpc_nodes','cloud_mining','articles')) r) IS DISTINCT FROM convert_from(decode('5b5d','hex'),'UTF8')::jsonb THEN RAISE EXCEPTION 'Preflight drift on module_catalog; no writes.'; END IF;
IF EXISTS(SELECT 1 FROM pg_class WHERE oid='public.entitlement_definitions'::regclass AND (relrowsecurity OR relforcerowsecurity))
      OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.entitlement_definitions'::regclass AND NOT tgisinternal AND tgenabled<>'D') THEN
      RAISE EXCEPTION 'Unexpected security/trigger configuration on entitlement_definitions; review required.'; END IF;
    IF (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY key),'[]'::jsonb) FROM (SELECT key,label,kind,value_type FROM public.entitlement_definitions WHERE key IN ('crypto_exchange','swap','convert','buy','sell','website','merchant_api','api_keys','webhooks','crypto_payments','crypto_card','staking','earn','dex','telegram_bot','telegram_mini_app','whatsapp_bot','ios_app','android_app','crypto_engine','rpc_nodes','cloud_mining','articles','max_supported_assets','max_supported_networks','max_payment_methods','max_staff','max_api_keys','max_webhooks','max_monthly_transactions','max_monthly_volume')) r) IS DISTINCT FROM convert_from(decode('5b5d','hex'),'UTF8')::jsonb THEN RAISE EXCEPTION 'Preflight drift on entitlement_definitions; no writes.'; END IF;
IF EXISTS(SELECT 1 FROM pg_class WHERE oid='public.asset_catalog'::regclass AND (relrowsecurity OR relforcerowsecurity))
      OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.asset_catalog'::regclass AND NOT tgisinternal AND tgenabled<>'D') THEN
      RAISE EXCEPTION 'Unexpected security/trigger configuration on asset_catalog; review required.'; END IF;
    IF (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]'::jsonb) FROM (SELECT id,symbol,name FROM public.asset_catalog WHERE id IN ('btc','eth','usdt','sol','bnb')) r) IS DISTINCT FROM convert_from(decode('5b5d','hex'),'UTF8')::jsonb THEN RAISE EXCEPTION 'Preflight drift on asset_catalog; no writes.'; END IF;
IF EXISTS(SELECT 1 FROM pg_class WHERE oid='public.network_catalog'::regclass AND (relrowsecurity OR relforcerowsecurity))
      OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.network_catalog'::regclass AND NOT tgisinternal AND tgenabled<>'D') THEN
      RAISE EXCEPTION 'Unexpected security/trigger configuration on network_catalog; review required.'; END IF;
    IF (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]'::jsonb) FROM (SELECT id,name,testnet FROM public.network_catalog WHERE id IN ('bitcoin-testnet','ethereum-sepolia','solana-devnet','bsc-testnet','tron-nile')) r) IS DISTINCT FROM convert_from(decode('5b5d','hex'),'UTF8')::jsonb THEN RAISE EXCEPTION 'Preflight drift on network_catalog; no writes.'; END IF;
IF EXISTS(SELECT 1 FROM pg_class WHERE oid='public.asset_network_catalog'::regclass AND (relrowsecurity OR relforcerowsecurity))
      OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.asset_network_catalog'::regclass AND NOT tgisinternal AND tgenabled<>'D') THEN
      RAISE EXCEPTION 'Unexpected security/trigger configuration on asset_network_catalog; review required.'; END IF;
    IF (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]'::jsonb) FROM (SELECT id,asset_id,network_id FROM public.asset_network_catalog WHERE id IN ('btc:bitcoin-testnet','eth:ethereum-sepolia','usdt:ethereum-sepolia','sol:solana-devnet','bnb:bsc-testnet','usdt:bsc-testnet','usdt:tron-nile')) r) IS DISTINCT FROM convert_from(decode('5b5d','hex'),'UTF8')::jsonb THEN RAISE EXCEPTION 'Preflight drift on asset_network_catalog; no writes.'; END IF;
IF EXISTS(SELECT 1 FROM pg_class WHERE oid='public.landing_products'::regclass AND (relrowsecurity OR relforcerowsecurity))
      OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.landing_products'::regclass AND NOT tgisinternal AND tgenabled<>'D') THEN
      RAISE EXCEPTION 'Unexpected security/trigger configuration on landing_products; review required.'; END IF;
    IF (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY key),'[]'::jsonb) FROM (SELECT key,visible,name,description,icon,starting_price::text AS starting_price,setup_fee::text AS setup_fee,currency,billing_period,status,cta_label,display_order FROM public.landing_products WHERE key IN ('crypto_exchange','crypto_payments','crypto_engine','ios_app','android_app','crypto_card','staking','earn','dex','articles','telegram_bot','telegram_mini_app','whatsapp_bot','rpc_nodes','cloud_mining')) r) IS DISTINCT FROM convert_from(decode('5b5d','hex'),'UTF8')::jsonb THEN RAISE EXCEPTION 'Preflight drift on landing_products; no writes.'; END IF;
