$qx_global$;

-- Approved named CHECK correction; its original structural guards are retained.
DO $qx_recovery$
DECLARE
  actual_definition text;
  is_validated boolean;
  old_definition constant text := 'CHECK (((status = ''delivered''::text) = (tenant_id IS NOT NULL)))';
  new_definition constant text := 'CHECK (((status <> ''delivered''::text) OR (tenant_id IS NOT NULL)))';
BEGIN
  IF EXISTS (SELECT 1 FROM pg_event_trigger WHERE evtenabled<>'D') THEN
    RAISE EXCEPTION 'Active DDL event triggers require separate review.';
  END IF;
  SELECT pg_get_constraintdef(c.oid),c.convalidated
    INTO actual_definition,is_validated
  FROM pg_constraint c
  WHERE c.conrelid='public.white_label_requests'::regclass
    AND c.conname='white_label_request_delivery' AND c.contype='c';
  IF actual_definition IS NULL OR NOT is_validated THEN
    RAISE EXCEPTION 'Missing or unvalidated delivery constraint; stop for review.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_attribute
    WHERE attrelid='public.white_label_requests'::regclass
      AND attname='status' AND attnotnull AND NOT attisdropped) THEN
    RAISE EXCEPTION 'Unexpected status nullability; stop for review.';
  END IF;
  IF actual_definition = new_definition THEN
    RAISE NOTICE 'Current Development delivery constraint already installed; no change.';
  ELSIF actual_definition = old_definition THEN
    -- Every row accepted by the validated old predicate satisfies the new one.
    -- PostgreSQL validates existing rows again when adding this CHECK.
    ALTER TABLE public.white_label_requests
      DROP CONSTRAINT white_label_request_delivery,
      ADD CONSTRAINT white_label_request_delivery
        CHECK (status <> 'delivered' OR tenant_id IS NOT NULL);
  ELSE
    RAISE EXCEPTION 'Delivery definition differs from reviewed snapshot; stop for review.';
  END IF;
END;
$qx_recovery$;

-- Approved global writes and exact original postcondition comparisons.
DO $qx_global$
BEGIN
INSERT INTO public.module_catalog(key,name,description,category,sandbox_available,definition) SELECT key,name,description,category,sandbox_available,definition FROM jsonb_to_recordset(convert_from(decode('','hex'),'UTF8')::jsonb) AS r(key text,name text,description text,category text,sandbox_available boolean,definition jsonb);
INSERT INTO public.entitlement_definitions(key,label,kind,value_type) SELECT key,label,kind,value_type FROM jsonb_to_recordset(convert_from(decode('','hex'),'UTF8')::jsonb) AS r(key text,label text,kind text,value_type text);
INSERT INTO public.asset_catalog(id,symbol,name) SELECT id,symbol,name FROM jsonb_to_recordset(convert_from(decode('','hex'),'UTF8')::jsonb) AS r(id text,symbol text,name text);
INSERT INTO public.network_catalog(id,name,testnet) SELECT id,name,testnet FROM jsonb_to_recordset(convert_from(decode('','hex'),'UTF8')::jsonb) AS r(id text,name text,testnet boolean);
INSERT INTO public.asset_network_catalog(id,asset_id,network_id) SELECT id,asset_id,network_id FROM jsonb_to_recordset(convert_from(decode('','hex'),'UTF8')::jsonb) AS r(id text,asset_id text,network_id text);
INSERT INTO public.landing_products(key,visible,name,description,icon,starting_price,setup_fee,currency,billing_period,status,cta_label,display_order) SELECT key,visible,name,description,icon,starting_price,setup_fee,currency,billing_period,status,cta_label,display_order FROM jsonb_to_recordset(convert_from(decode('','hex'),'UTF8')::jsonb) AS r(key text,visible boolean,name text,description text,icon text,starting_price numeric,setup_fee numeric,currency text,billing_period text,status text,cta_label text,display_order integer);
UPDATE public.landing_products SET visible=true WHERE key IN (SELECT jsonb_array_elements_text(convert_from(decode('5b5d','hex'),'UTF8')::jsonb)) AND visible=false;
IF (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY key),'[]'::jsonb) FROM (SELECT key,name,description,category,sandbox_available,definition FROM public.module_catalog WHERE key IN ('crypto_exchange','website','merchant_api','crypto_payments','crypto_card','staking','earn','dex','telegram_bot','telegram_mini_app','whatsapp_bot','ios_app','android_app','crypto_engine','rpc_nodes','cloud_mining','articles')) r) IS DISTINCT FROM convert_from(decode('','hex'),'UTF8')::jsonb THEN RAISE EXCEPTION 'Postcondition failed on module_catalog; roll back.'; END IF;
IF (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY key),'[]'::jsonb) FROM (SELECT key,label,kind,value_type FROM public.entitlement_definitions WHERE key IN ('crypto_exchange','swap','convert','buy','sell','website','merchant_api','api_keys','webhooks','crypto_payments','crypto_card','staking','earn','dex','telegram_bot','telegram_mini_app','whatsapp_bot','ios_app','android_app','crypto_engine','rpc_nodes','cloud_mining','articles','max_supported_assets','max_supported_networks','max_payment_methods','max_staff','max_api_keys','max_webhooks','max_monthly_transactions','max_monthly_volume')) r) IS DISTINCT FROM convert_from(decode('','hex'),'UTF8')::jsonb THEN RAISE EXCEPTION 'Postcondition failed on entitlement_definitions; roll back.'; END IF;
IF (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]'::jsonb) FROM (SELECT id,symbol,name FROM public.asset_catalog WHERE id IN ('btc','eth','usdt','sol','bnb')) r) IS DISTINCT FROM convert_from(decode('','hex'),'UTF8')::jsonb THEN RAISE EXCEPTION 'Postcondition failed on asset_catalog; roll back.'; END IF;
IF (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]'::jsonb) FROM (SELECT id,name,testnet FROM public.network_catalog WHERE id IN ('bitcoin-testnet','ethereum-sepolia','solana-devnet','bsc-testnet','tron-nile')) r) IS DISTINCT FROM convert_from(decode('','hex'),'UTF8')::jsonb THEN RAISE EXCEPTION 'Postcondition failed on network_catalog; roll back.'; END IF;
IF (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]'::jsonb) FROM (SELECT id,asset_id,network_id FROM public.asset_network_catalog WHERE id IN ('btc:bitcoin-testnet','eth:ethereum-sepolia','usdt:ethereum-sepolia','sol:solana-devnet','bnb:bsc-testnet','usdt:bsc-testnet','usdt:tron-nile')) r) IS DISTINCT FROM convert_from(decode('','hex'),'UTF8')::jsonb THEN RAISE EXCEPTION 'Postcondition failed on asset_network_catalog; roll back.'; END IF;
IF (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY key),'[]'::jsonb) FROM (SELECT key,visible,name,description,icon,starting_price::text AS starting_price,setup_fee::text AS setup_fee,currency,billing_period,status,cta_label,display_order FROM public.landing_products WHERE key IN ('crypto_exchange','crypto_payments','crypto_engine','ios_app','android_app','crypto_card','staking','earn','dex','articles','telegram_bot','telegram_mini_app','whatsapp_bot','rpc_nodes','cloud_mining')) r) IS DISTINCT FROM convert_from(decode('','hex'),'UTF8')::jsonb THEN RAISE EXCEPTION 'Postcondition failed on landing_products; roll back.'; END IF;
END;
$qx_global$;

-- Final Landing verification and readback before commit.
DO $qx_landing_verification$
BEGIN
  IF (SELECT count(*) FROM public.landing_products WHERE visible) <> 15
     OR EXISTS (SELECT 1 FROM public.landing_products WHERE key='kolo' AND visible) THEN
    RAISE EXCEPTION 'Landing verification failed: expected exactly 15 visible products and no visible Kolo; roll back.';
  END IF;
END;
$qx_landing_verification$;
SELECT conname,convalidated,pg_get_constraintdef(oid) AS definition
FROM pg_constraint
WHERE conrelid='public.white_label_requests'::regclass
