SELECT 'module_catalog' AS scope,count(*) AS reviewed_records FROM public.module_catalog WHERE key IN ('crypto_exchange','website','merchant_api','crypto_payments','crypto_card','staking','earn','dex','telegram_bot','telegram_mini_app','whatsapp_bot','ios_app','android_app','crypto_engine','rpc_nodes','cloud_mining','articles')
