UNION ALL
SELECT 'landing_products' AS scope,count(*) AS reviewed_records FROM public.landing_products WHERE key IN ('crypto_exchange','crypto_payments','crypto_engine','ios_app','android_app','crypto_card','staking','earn','dex','articles','telegram_bot','telegram_mini_app','whatsapp_bot','rpc_nodes','cloud_mining');

